using SVector2 = System.Numerics.Vector2;

namespace OpenTPW;

/// <summary>
/// Draws the park's pool cells (docs/POOLS.md): an animated water surface (<c>content/shaders/pool-water.shader</c>, adapted from the unused
/// <c>water.shader</c> of the lake entity <see cref="Water"/>) and the coping and walls of the rim, all generated by <see cref="PoolMeshBuilder"/> from the cells and the land's
/// corner heights, with textures generated in code (<see cref="PoolTextures"/>). The mesh is rebuilt when the set of pool cells changes. Presentation only: nothing here
/// touches the simulation. GPU code: the mesh itself is tested on the CPU.
/// </summary>
// [EXT:pools-render] OpenTPW's own pool rendering; the original game has no pools
public sealed class PoolRenderer : Entity
{
	private readonly ParkCellMap cells;
	private readonly IParkGrid terrain;
	private readonly float cellSize;
	private readonly PoolMeshOptions options;
	private readonly ModelEntity water = new();
	private readonly ModelEntity coping = new();
	private readonly ModelEntity walls = new();
	private readonly Texture waterTexture;
	private readonly Texture copingTexture;
	private readonly Texture wallTexture;
	private readonly Material<ObjectUniformBuffer> waterMaterial;
	private readonly Material<ObjectUniformBuffer> copingMaterial;
	private readonly Material<ObjectUniformBuffer> wallMaterial;
	private int seenVersion = -1;
	private ulong seenSignature;
	private bool deleted;

	/// <summary>The cells drawn in the last build.</summary>
	public int DrawnCells { get; private set; }
	/// <summary>Triangles of the last build (water, coping and walls).</summary>
	public int Triangles { get; private set; }

	public PoolRenderer( ParkCellMap cells, IParkGrid terrain, float cellSize = OriginalParkPlacement.CellSize, PoolMeshOptions? options = null )
	{
		this.cells = cells ?? throw new ArgumentNullException( nameof( cells ) );
		this.terrain = terrain ?? throw new ArgumentNullException( nameof( terrain ) );
		this.cellSize = cellSize;
		this.options = options ?? PoolMeshOptions.Default;
		Name = "Pools";
		waterTexture = new Texture( PoolTextures.Water(), PoolTextures.Size, PoolTextures.Size, TextureFlags.Wrap );
		copingTexture = new Texture( PoolTextures.Coping(), PoolTextures.Size, PoolTextures.Size, TextureFlags.Wrap );
		wallTexture = new Texture( PoolTextures.Wall(), PoolTextures.Size, PoolTextures.Size, TextureFlags.Wrap );
		waterMaterial = new Material<ObjectUniformBuffer>( "content/shaders/pool-water.shader", MaterialFlags.DoubleSided );
		waterMaterial.Set( "Color", waterTexture );
		copingMaterial = new Material<ObjectUniformBuffer>( "content/shaders/3d.shader", MaterialFlags.DoubleSided );
		copingMaterial.Set( "Color", copingTexture );
		wallMaterial = new Material<ObjectUniformBuffer>( "content/shaders/3d.shader", MaterialFlags.DoubleSided );
		wallMaterial.Set( "Color", wallTexture );
		foreach ( var part in new[] { water, coping, walls } )
			part.Cullable = true;
	}

	/// <summary>The pool cells of the map in row order.</summary>
	public static List<(int X, int Y)> PoolCells( ParkCellMap cells )
	{
		var list = new List<(int X, int Y)>();
		if ( cells.CountOf( ParkCellType.PoolWater ) == 0 )
			return list;
		for ( var y = 0; y < cells.Height; y++ )
			for ( var x = 0; x < cells.Width; x++ )
				if ( cells.RawTypeAt( x, y ) == ParkCellTypes.PoolWater )
					list.Add( (x, y) );
		return list;
	}

	/// <summary>Builds the mesh of the map's pool cells now.</summary>
	public PoolMesh BuildMesh( IEnumerable<(int X, int Y)> poolCells ) =>
		PoolMeshBuilder.Build( poolCells, ( x, y ) => cells.RawTypeAt( x, y ) == ParkCellTypes.PoolWater, Ground, terrain.Origin, cellSize, options );

	/// <summary>
	/// The ground height at a point in cell units, from the terrain's sampler (<see cref="LandscapeSampler"/> through <see cref="IParkGrid.GetTerrainHeight"/>, which takes model units, 10 to
	/// a cell): the height the land is drawn at, so the coping and the water follow it. The sampler answers 0 on the map's far edge, so the point is held just inside.
	/// </summary>
	private float Ground( float cellX, float cellY ) =>
		terrain.GetTerrainHeight( Math.Min( cellX * LandscapeSampler.CellUnits, terrain.Width * LandscapeSampler.CellUnits - 0.001f ),
			Math.Min( cellY * LandscapeSampler.CellUnits, terrain.Height * LandscapeSampler.CellUnits - 0.001f ) );

	protected override void OnUpdate()
	{
		if ( deleted || cells.Version == seenVersion )
			return;
		seenVersion = cells.Version;
		var poolCells = PoolCells( cells );
		var signature = Signature( poolCells );
		if ( signature == seenSignature && (poolCells.Count == DrawnCells) )
			return;
		seenSignature = signature;
		DrawnCells = poolCells.Count;
		var mesh = BuildMesh( poolCells );
		Triangles = mesh.Water.TriangleCount + mesh.Coping.TriangleCount + mesh.Walls.TriangleCount;
		Replace( water, mesh.Water, waterMaterial );
		Replace( coping, mesh.Coping, copingMaterial );
		Replace( walls, mesh.Walls, wallMaterial );
	}

	private static ulong Signature( IReadOnlyList<(int X, int Y)> poolCells )
	{
		var hash = 14695981039346656037UL;
		foreach ( var (x, y) in poolCells )
			hash = (hash ^ (uint)(y * 4096 + x)) * 1099511628211UL;
		return hash;
	}

	private static void Replace( ModelEntity entity, PoolMeshPart part, Material material )
	{
		entity.Model?.ReleaseBuffers();
		entity.Model = null;
		if ( part.Vertices.Count == 0 )
			return;
		var vertices = part.Vertices.Select( vertex => new Vertex( vertex.Position, vertex.Normal, vertex.Uv ) ).ToArray();
		entity.Model = new Model( vertices, part.Indices.Select( index => (uint)index ).ToArray(), material );
	}

	protected override void OnDelete()
	{
		deleted = true;
		foreach ( var part in new[] { water, coping, walls } )
		{
			part.Model?.ReleaseBuffers();
			part.Model = null;
			part.Delete();
		}
		foreach ( var texture in new[] { waterTexture, copingTexture, wallTexture } )
			texture.ReleaseOwned();
		foreach ( var material in new Material[] { waterMaterial, copingMaterial, wallMaterial } )
			material.ReleaseOwnedResources();
	}
}
